$$\begin{array}{l}
\mathrm{t}=\sqrt{\frac{2 \mathrm{~h}}{\mathrm{~g}}}=\sqrt{\frac{2 \times 80}{10}} \\
=4 \mathrm{sec}
\end{array}$$

$\frac{\mathrm{A}}{\mathrm{A}_{0}}=\frac{\mathrm{N}}{\mathrm{N}_{0}}$
$$\begin{array}{l}
\frac{2 \times 10^{-5}}{2.56 \times 10^{-3}}=\frac{\mathrm{N}}{\mathrm{~N}_{0}} \\
\frac{\mathrm{~N}}{\mathrm{~N}_{0}}=\frac{1}{128} \Rightarrow \mathrm{~N}=\frac{\mathrm{N}_{0}}{128}
\end{array}$$

$\mathrm{F}=\frac{\mathrm{dp}}{\mathrm{dt}}=\mathrm{v} \frac{\mathrm{dm}}{\mathrm{dt}}$
$$\begin{array}{l}
\Rightarrow \mathrm{Ma}=10 \times 1 \\
\Rightarrow 2 \mathrm{a}=10 \\
\mathrm{a}=5 \mathrm{~m} / \mathrm{sec}^{2}
\end{array}$$

$\left(\mathrm{a}^{2}+\mathrm{b}^{2}+2 \mathrm{ab} \cos \theta\right)=4\left(\mathrm{a}^{2}+\mathrm{b}^{2}-2 \mathrm{ab} \cos \theta\right)$ put $\mathrm{a}=\mathrm{b}$ we get
$$\begin{array}{l}
2 a^{2}+2 a^{2} \cos \theta=8 a^{2}-8 a^{2} \cos \theta \\
\cos \theta=\frac{3}{5}
\end{array}$$

Fringe width $\beta=\frac{\mathrm{D} \lambda}{\mathrm{d}}$
$$\begin{array}{l}
\lambda_{1}=5000 \AA \\
\beta_{1}=\frac{D}{d}\left(5000 \times 10^{-10}\right)=5 \times 10^{-4} \mathrm{~m} \\
\beta_{2}=\frac{D}{(2 d)}\left(6000 \times 10^{-10}\right)=x \text { (let) }
\end{array}$$

Divide (II) \& (I)
$$\begin{array}{l}
\frac{\beta_{2}}{\beta_{1}}=\frac{3000 \times 10^{-10}}{5000 \times 10^{-10}}=\frac{x}{5 \times 10^{-4}} \\
x=3 \times 10^{-4} \mathrm{~m} \text { or } 0.3 \mathrm{~mm}
\end{array}$$

